import java.util.function.Function;

public class ApiClient {
  interface Limiter { boolean allow(String key, long now); }

  final Limiter limiter;
  final Function<String, String> request;
  final int maxAttempts;
  long now;

  ApiClient(Limiter limiter, Function<String, String> request, int maxAttempts) {
    this.limiter = limiter;
    this.request = request;
    this.maxAttempts = maxAttempts;
  }

  String call(String key, String input) {
    RuntimeException last = new RuntimeException("no attempt");
    for (int attempt = 1; attempt <= maxAttempts; attempt++) {
      if (!limiter.allow(key, now)) last = new RuntimeException("limited");
      else {
        try {
          return request.apply(input);
        } catch (RuntimeException ex) {
          last = ex;
        }
      }
      now += 10L * (1L << (attempt - 1));
    }
    throw last;
  }

  public static void main(String[] args) {
    int[] calls = { 0 };
    ApiClient client = new ApiClient( (key, now) -> true, input -> {
      calls[0] += 1;
      if (calls[0] < 3) throw new RuntimeException("flaky");
      return "ok";
    }, 3);
    if (!client.call("user", "ping").equals("ok") || calls[0] != 3) throw new RuntimeException("retry");
    System.out.println("ok");
  }
}

atm.javascript:
export class Atm {
  constructor(cash) {
    this.cash = cash;
    this.accounts = new Map();
  }
  open(id, pin, balance) {
    this.accounts.set(id, { pin, balance });
  }
  withdraw(id, pin, amount) {
    const account = this.auth(id, pin);
    if (!Number.isInteger(amount) || amount <= 0) throw new Error("amount");
    if (amount > account.balance) throw new Error("funds");
    if (amount > this.cash) throw new Error("cash");
    account.balance -= amount;
    this.cash -= amount;
    return account.balance;
  }
  deposit(id, pin, amount) {
    const account = this.auth(id, pin);
    if (!Number.isInteger(amount) || amount <= 0) throw new Error("amount");
    account.balance += amount;
    this.cash += amount;
    return account.balance;
  }
  auth(id, pin) {
    const account = this.accounts.get(id);
    if (!account || account.pin !== pin) throw new Error("auth");
    return account;
  }
}

export function demo() {
  const atm = new Atm(40);
  atm.open("ada", "1234", 100);
  if (atm.withdraw("ada", "1234", 30) !== 70) throw new Error("balance");
  let broke = false;
  try { atm.withdraw("ada", "1234", 90); } catch { broke = true; }
  if (!broke || atm.cash !== 10) throw new Error("funds stay put");
  let empty = false;
  try { atm.withdraw("ada", "1234", 20); } catch { empty = true; }
  if (!empty) throw new Error("machine cash");
}

if (import.meta.main) demo();

