// The holder class is initialized once, by the class loader, even if threads race.

public class ThreadSafeSingleton {
  static class Settings {
    final int retries = 3;

    private Settings() {}

    private static class Holder {
      static final Settings ONE = new Settings();
    }

    static Settings get() {
      return Holder.ONE;
    }
  }

  public static void main(String[] args) throws Exception {
    Settings[] seen = new Settings[8];
    Thread[] threads = new Thread[seen.length];
    for (int i = 0; i < threads.length; i++) {
      int n = i;
      threads[i] = new Thread(() -> seen[n] = Settings.get());
    }
    for (Thread thread : threads) thread.start();
    for (Thread thread : threads) thread.join();
    for (Settings settings : seen) {
      if (settings != Settings.get()) throw new RuntimeException("racy second instance");
    }
    System.out.println("ok");
  }
}

tic-tac-toe.javascript:
export class TicTacToe {
  constructor(size = 3) {
    this.size = size;
    this.board = Array.from({ length: size }, () => Array(size).fill(null));
    this.turn = "X";
    this.winner = null;
  }
  play(row, col) {
    if (this.winner || this.board[row]?.[col] !== null) throw new Error("illegal");
    this.board[row][col] = this.turn;
    if (this.line(this.turn)) this.winner = this.turn;
    else if (this.board.every((line) => line.every(Boolean))) this.winner = "draw";
    else this.turn = this.turn === "X" ? "O" : "X";
    return this.winner;
  }
  line(mark) {
    const n = this.size;
    const row = this.board.some((line) => line.every((cell) => cell === mark));
    const col = Array.from({ length: n }, (_, c) => this.board.every((line) => line[c] === mark)).some(Boolean);
    const diag = this.board.every((line, i) => line[i] === mark);
    const anti = this.board.every((line, i) => line[n - 1 - i] === mark);
    return row || col || diag || anti;
  }
}

export function demo() {
  const game = new TicTacToe();
  game.play(0, 0);
  game.play(1, 0);
  game.play(0, 1);
  game.play(1, 1);
  if (game.play(0, 2) !== "X") throw new Error("X wins the row");
  let refused = false;
  try { game.play(2, 2); } catch { refused = true; }
  if (!refused) throw new Error("game over");
}

if (import.meta.main) demo();

tic-tac-toe.java:
public class TicTacToe {
  final int size;
  final String[][] board;
  String turn = "X";
  String winner;

  TicTacToe(int size) {
    this.size = size;
    board = new String[size][size];
  }

  String play(int row, int col) {
    if (winner != null || board[row][col] != null) throw new IllegalStateException("illegal");
    board[row][col] = turn;
    if (line(turn)) winner = turn;
    else if (full()) winner = "draw";
    else turn = turn.equals("X") ? "O" : "X";
    return winner;
  }

  private boolean full() {
    for (String[] line : board) for (String cell : line) if (cell == null) return false;
    return true;
  }

  private boolean line(String mark) {
    for (int r = 0; r < size; r++) {
      boolean row = true;
      for (int c = 0; c < size; c++) row &= mark.equals(board[r][c]);
      if (row) return true;
    }
    for (int c = 0; c < size; c++) {
      boolean col = true;
      for (int r = 0; r < size; r++) col &= mark.equals(board[r][c]);
      if (col) return true;
    }
    boolean diag = true;
    boolean anti = true;
    for (int i = 0; i < size; i++) {
      diag &= mark.equals(board[i][i]);
      anti &= mark.equals(board[i][size - 1 - i]);
    }
    return diag || anti;
  }

  public static void main(String[] args) {
    TicTacToe game = new TicTacToe(3);
    game.play(0, 0);
    game.play(1, 0);
    game.play(0, 1);
    game.play(1, 1);
    if (!"X".equals(game.play(0, 2))) throw new RuntimeException("X wins the row");
    boolean refused = false;
    try { game.play(2, 2); } catch (IllegalStateException ex) { refused = true; }
    if (!refused) throw new RuntimeException("game over");
    System.out.println("ok");
  }
}

traffic-signal.javascript:
const CYCLE = [
  { name: "green", span: 4 },
  { name: "yellow", span: 1 },
  { name: "red", span: 4 },
];

export class Signal {
  constructor() {
    this.index = 0;
    this.left = CYCLE[0].span;
    this.emergency = false;
  }
  color() {
    return this.emergency ? "red" : CYCLE[this.index].name;
  }
  tick() {
    if (this.emergency) return this.color();
    this.left -= 1;
    if (this.left === 0) {
      this.index = (this.index + 1) % CYCLE.length;
      this.left = CYCLE[this.index].span;
    }
    return this.color();
  }
  emergencyStop() {
    this.emergency = true;
  }
  resume() {
    this.emergency = false;
  }
}

export function demo() {
  const signal = new Signal();
  if (signal.color() !== "green") throw new Error("start");
  signal.tick();
  signal.tick();
  signal.tick();
  if (signal.tick() !== "yellow") throw new Error("yellow");
  if (signal.tick() !== "red") throw new Error("red");
  signal.emergencyStop();
  if (signal.tick() !== "red") throw new Error("hold");
  signal.resume();
  if (signal.color() !== "red") throw new Error("same phase");
}

if (import.meta.main) demo();

