import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class Vending {
  static final int[] DENOMS = {25, 10, 5, 1};

  static class Item {
    final int price;
    int stock;
    Item(int price, int stock) { this.price = price; this.stock = stock; }
  }

  static class Sale {
    final boolean ok;
    final String item;
    final List<int[]> change;
    final List<Integer> refund;
    Sale(boolean ok, String item, List<int[]> change, List<Integer> refund) {
      this.ok = ok;
      this.item = item;
      this.change = change;
      this.refund = refund;
    }
  }

  final Map<String, Item> items = new LinkedHashMap<>();
  final Map<Integer, Integer> box = new LinkedHashMap<>();
  final List<Integer> inserted = new ArrayList<>();

  Vending() {
    for (int denom : DENOMS) box.put(denom, 0);
  }

  void add(String id, int price, int stock) { items.put(id, new Item(price, stock)); }
  void load(int denom, int count) { box.put(denom, box.get(denom) + count); }
  void insert(int denom) { inserted.add(denom); }

  int credit() {
    int sum = 0;
    for (int coin : inserted) sum += coin;
    return sum;
  }

  List<Integer> refund() {
    List<Integer> coins = new ArrayList<>(inserted);
    inserted.clear();
    return coins;
  }

  Sale buy(String id) {
    Item item = items.get(id);
    if (item == null || item.stock < 1) throw new IllegalStateException("out of stock");
    int credit = credit();
    if (credit < item.price) throw new IllegalStateException("insert more");
    Map<Integer, Integer> pool = new LinkedHashMap<>(box);
    for (int coin : inserted) pool.put(coin, pool.get(coin) + 1);
    List<int[]> plan = planChange(pool, credit - item.price);
    if (plan == null) return new Sale(false, null, null, refund());
    for (int coin : inserted) box.put(coin, box.get(coin) + 1);
    for (int[] row : plan) box.put(row[0], box.get(row[0]) - row[1]);
    inserted.clear();
    item.stock -= 1;
    return new Sale(true, id, plan, null);
  }

  static List<int[]> planChange(Map<Integer, Integer> pool, int cents) {
    List<int[]> plan = new ArrayList<>();
    int left = cents;
    for (int denom : DENOMS) {
      int use = Math.min(pool.get(denom), left / denom);
      if (use > 0) plan.add(new int[] {denom, use});
      left -= use * denom;
    }
    return left == 0 ? plan : null;
  }

  public static void main(String[] args) {
    Vending machine = new Vending();
    machine.add("soda", 65, 1);
    machine.load(10, 5);
    machine.insert(25);
    machine.insert(25);
    boolean shortPay = false;
    try { machine.buy("soda"); } catch (IllegalStateException ex) { shortPay = true; }
    if (!shortPay) throw new RuntimeException("needs 65");
    machine.insert(25);
    Sale sold = machine.buy("soda");
    int back = 0;
    for (int[] row : sold.change) back += row[0] * row[1];
    if (!sold.ok || back != 10) throw new RuntimeException("dime back");
    machine.insert(25);
    if (machine.refund().get(0) != 25) throw new RuntimeException("refund");
    Vending empty = new Vending();
    empty.add("soda", 30, 1);
    empty.insert(25);
    empty.insert(10);
    Sale stuck = empty.buy("soda");
    int refund = 0;
    for (int coin : stuck.refund) refund += coin;
    if (stuck.ok || refund != 35) throw new RuntimeException("cannot make a nickel");
    System.out.println("ok");
  }
}

versioned-kv.javascript:
export class VersionedKv {
  constructor() {
    this.rows = new Map();
  }
  put(key, value, expected) {
    const history = this.rows.get(key) ?? [];
    const current = history.length;
    if (current !== expected) throw new Error(`conflict ${current}`);
    history.push(value);
    this.rows.set(key, history);
    return current + 1;
  }
  get(key) {
    const history = this.rows.get(key) ?? [];
    if (!history.length) return undefined;
    return { value: history[history.length - 1], version: history.length };
  }
  at(key, version) {
    const history = this.rows.get(key) ?? [];
    if (version < 1 || version > history.length) throw new Error("version");
    return history[version - 1];
  }
}

export function demo() {
  const store = new VersionedKv();
  if (store.put("a", "one", 0) !== 1) throw new Error("first");
  let clash = false;
  try { store.put("a", "two", 0); } catch { clash = true; }
  if (!clash) throw new Error("stale write");
  store.put("a", "two", 1);
  if (store.get("a").value !== "two" || store.at("a", 1) !== "one") throw new Error("history");
}

if (import.meta.main) demo();

versioned-kv.java:
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class VersionedKv {
  static class View {
    final String value;
    final int version;
    View(String value, int version) { this.value = value; this.version = version; }
  }

  final Map<String, List<String>> rows = new HashMap<>();

  int put(String key, String value, int expected) {
    List<String> history = rows.computeIfAbsent(key, ignored -> new ArrayList<>());
    if (history.size() != expected) throw new IllegalStateException("conflict " + history.size());
    history.add(value);
    return history.size();
  }

  View get(String key) {
    List<String> history = rows.get(key);
    if (history == null || history.isEmpty()) return null;
    return new View(history.get(history.size() - 1), history.size());
  }

  String at(String key, int version) {
    List<String> history = rows.getOrDefault(key, List.of());
    if (version < 1 || version > history.size()) throw new IllegalArgumentException("version");
    return history.get(version - 1);
  }

  public static void main(String[] args) {
    VersionedKv store = new VersionedKv();
    if (store.put("a", "one", 0) != 1) throw new RuntimeException("first");
    boolean clash = false;
    try { store.put("a", "two", 0); } catch (IllegalStateException ex) { clash = true; }
    if (!clash) throw new RuntimeException("stale write");
    store.put("a", "two", 1);
    if (!store.get("a").value.equals("two") || !store.at("a", 1).equals("one")) throw new RuntimeException("history");
    System.out.println("ok");
  }
}

