export class Workflow {
  constructor(steps) {
    this.steps = steps.map((step) => ({ ...step, status: "pending", tries: 0 }));
  }
  ready() {
    return this.steps.filter((step) => step.status === "pending" && step.needs.every((id) => this.by(id).status === "done"));
  }
  run(id) {
    const step = this.by(id);
    if (!this.ready().includes(step)) throw new Error("blocked");
    step.tries += 1;
    try {
      step.work();
      step.status = "done";
    } catch (error) {
      step.status = "failed";
      step.error = error.message;
    }
    return step.status;
  }
  retry(id) {
    const step = this.by(id);
    if (step.status !== "failed") throw new Error("not failed");
    step.status = "pending";
  }
  by(id) {
    const step = this.steps.find((row) => row.id === id);
    if (!step) throw new Error("missing");
    return step;
  }
}

export function demo() {
  let pay = 0;
  const flow = new Workflow([
    { id: "reserve", needs: [], work() {} },
    { id: "pay", needs: ["reserve"], work() { pay += 1; if (pay < 2) throw new Error("bank"); } },
    { id: "ship", needs: ["pay"], work() {} },
  ]);
  if (flow.ready().map((step) => step.id).join(",") !== "reserve") throw new Error("deps");
  flow.run("reserve");
  if (flow.run("pay") !== "failed") throw new Error("first pay fails");
  let blocked = false;
  try { flow.run("ship"); } catch { blocked = true; }
  if (!blocked) throw new Error("ship waits");
  flow.retry("pay");
  if (flow.run("pay") !== "done" || flow.run("ship") !== "done") throw new Error("recovered");
}

if (import.meta.main) demo();

workflow.java:
import java.util.ArrayList;
import java.util.List;

public class Workflow {
  static class Step {
    final String id;
    final List<String> needs;
    final Runnable work;
    String status = "pending";
    Step(String id, List<String> needs, Runnable work) { this.id = id; this.needs = needs; this.work = work; }
  }

  final List<Step> steps = new ArrayList<>();

  void add(String id, List<String> needs, Runnable work) { steps.add(new Step(id, needs, work)); }

  List<Step> ready() {
    List<Step> out = new ArrayList<>();
    for (Step step : steps) {
      if (!step.status.equals("pending")) continue;
      boolean ok = true;
      for (String need : step.needs) if (!by(need).status.equals("done")) ok = false;
      if (ok) out.add(step);
    }
    return out;
  }

  String run(String id) {
    Step step = by(id);
    if (!ready().contains(step)) throw new IllegalStateException("blocked");
    try {
      step.work.run();
      step.status = "done";
    } catch (RuntimeException ex) {
      step.status = "failed";
    }
    return step.status;
  }

  void retry(String id) {
    Step step = by(id);
    if (!step.status.equals("failed")) throw new IllegalStateException("not failed");
    step.status = "pending";
  }

  Step by(String id) {
    for (Step step : steps) if (step.id.equals(id)) return step;
    throw new IllegalArgumentException("missing");
  }

  public static void main(String[] args) {
    int[] pay = {0};
    Workflow flow = new Workflow();
    flow.add("reserve", List.of(), () -> {});
    flow.add("pay", List.of("reserve"), () -> {
      pay[0] += 1;
      if (pay[0] < 2) throw new IllegalStateException("bank");
    });
    flow.add("ship", List.of("pay"), () -> {});
    if (!flow.ready().get(0).id.equals("reserve")) throw new RuntimeException("deps");
    flow.run("reserve");
    if (!flow.run("pay").equals("failed")) throw new RuntimeException("first pay fails");
    boolean blocked = false;
    try { flow.run("ship"); } catch (IllegalStateException ex) { blocked = true; }
    if (!blocked) throw new RuntimeException("ship waits");
    flow.retry("pay");
    if (!flow.run("pay").equals("done") || !flow.run("ship").equals("done")) throw new RuntimeException("recovered");
    System.out.println("ok");
  }
}
